# scripts/gen_site.py — render data/grants.csv to site/index.html (boss table).
# Single page, no external resources, noindex. The wiki/ pages are the source
# of truth; this is a projection, regenerated by scripts/publish.sh.
# Design: mobile-first card layout (owner direction 2026-10-27) — cards stack
# on phones (<700px) and run two columns on desktop. No horizontal scroll.
import csv, html, os, re, datetime

CODEWIKI_URL = ""   # set to the codewiki.google URL once Google indexes the repo

rows = [r for r in csv.DictReader(open('data/grants.csv', newline='', encoding='utf-8'))
        if r['status'] not in ('not_eligible', 'excluded')]
IN_HAND = {'applied', 'awarded', 'declined'}
active = [r for r in rows if r['status'] not in IN_HAND]
inhand = [r for r in rows if r['status'] in IN_HAND]
active.sort(key=lambda r: (r['next_deadline'] == '', r['next_deadline'],
                           r['grantor'], r['grant']))
inhand.sort(key=lambda r: (r['grantor'], r['grant']))
os.makedirs('site', exist_ok=True)

TODAY = datetime.date.today()

FOCUS_LABEL = {
    'family': 'Family', 'marriage': 'Marriage',
    'adult_faith_formation': 'Adult formation',
    'faith_formation': 'Faith formation', 'ocia': 'OCIA',
}
ENTITY_LABEL = {
    'diocesan_office': 'diocesan office', 'diocesan_or_parish': 'diocese or parish',
    'parish_only': 'parish only', 'school_only': 'schools only',
    'apostolate_any': 'any apostolate',
}

def amount(r):
    lo, hi = r['amount_min'], r['amount_max']
    def fmt(v):
        try:
            return f"${int(v):,}"
        except (ValueError, TypeError):
            return v
    if lo and hi:
        return f"{fmt(lo)} – {fmt(hi)}"
    return fmt(lo or hi) if (lo or hi) else '—'

def esc(v):
    return html.escape(v or '')

def status_chip(st):
    style = {'eligible': 'chip-eligible', 'maybe': 'chip-maybe',
             'researching': 'chip-research', 'applied': 'chip-inhand',
             'awarded': 'chip-eligible', 'declined': 'chip-inhand'}.get(st, '')
    return "<span class='chip %s'>%s</span>" % (style, esc(st))

def chips(row, mapping):
    parts = [p for p in re.split(r'[,\s]+', row or '') if p]
    return ''.join("<span class='mini'>%s</span>" % esc(mapping.get(p, p))
                   for p in parts)

def deadline_label(r):
    d = r['next_deadline']
    if not d:
        return "<span class='dl gray'>No deadline on the page now</span>"
    days = None
    try:
        days = (datetime.date.fromisoformat(d) - TODAY).days
    except ValueError:
        pass
    urgent = days is not None and 0 <= days <= 60
    cls = 'dl urgent' if urgent else 'dl'
    return "<span class='%s'>Next deadline: %s</span>" % (cls, esc(d))

def card(r, with_status=True, dim=False):
    cls = 'card dim' if dim else 'card'
    chip = status_chip(r['status']) if with_status else ''
    src = esc(r['source_url'])
    return "".join([
        "<div class='%s'>" % cls,
        "<div class='row1'><span class='grant'>%s</span>%s</div>" % (
            "<b>%s</b>" % esc(r['grant']), chip),
        "<div class='grantor'>%s</div>" % esc(r['grantor']),
        "<div class='meta'>%s</div>" % chips(r['focus_areas'], FOCUS_LABEL),
        "<div class='meta'><span class='mini q'>%s</span>"
        "<span class='mini q'>%s</span></div>" % (
            esc(amount(r)),
            esc(ENTITY_LABEL.get(r['grantee_entity'], r['grantee_entity']))),
        deadline_label(r),
        "<div class='mini'><a href='%s' rel='noopener'>verify at source</a></div>" % src,
        "</div>"])

cards_active = ''.join(card(r) for r in active)
cards_inhand = ''.join(card(r, with_status=False, dim=True) for r in inhand)

link_line = ("<p><a href='%s' rel='noopener'>Full wiki &rarr; Code Wiki</a></p>"
             % esc(CODEWIKI_URL)) if CODEWIKI_URL else ""

PAGE = """<!doctype html><html lang='en'><head><meta charset='utf-8'>
<meta name='viewport' content='width=device-width, initial-scale=1'>
<meta name='robots' content='noindex, nofollow'>
<meta name='theme-color' content='#111111'>
<title>Formation Grants — Active Opportunities</title>
<style>
*{box-sizing:border-box}
body{font-family:system-ui,sans-serif;margin:0;padding:0;background:#111;color:#eee;
-webkit-text-size-adjust:100%%}
.wrap{max-width:760px;margin:0 auto;padding:10px 12px 28px}
h1{font-size:17px;line-height:1.3;margin:8px 0 4px;padding:0}
.small{color:#9a9a9a;font-size:12px}
#q{width:100%%;padding:12px;font-size:16px;margin:10px 0 4px;border-radius:10px;
border:1px solid #444;background:#1c1c1c;color:#eee}
.section-head{font-size:13px;text-transform:uppercase;letter-spacing:.06em;color:#9a9a9a;
margin:18px 0 8px;font-weight:600}
.grid{display:grid;grid-template-columns:1fr;gap:8px}
@media(min-width:700px){.grid{grid-template-columns:1fr 1fr}}
.card{background:#1a1a1a;border:1px solid #2c2c2c;border-radius:12px;padding:12px 13px;
font-size:15px;line-height:1.35;word-wrap:break-word;overflow-wrap:break-word}
.card.dim{color:#b9b9b9}
.row1{display:flex;justify-content:space-between;gap:8px;align-items:baseline}
.row1 b{font-size:15.5px}
.grantor{color:#c9c9c9;font-size:13.5px;margin-top:3px}
.meta{display:flex;flex-wrap:wrap;gap:5px;margin-top:8px}
.mini{display:inline-block;background:#242424;border-radius:7px;padding:3px 8px;
font-size:12px;color:#cfcfcf}
.mini a{color:#7fb1ff;text-decoration:none}
.chip{display:inline-block;white-space:nowrap;border-radius:999px;padding:3px 10px;
font-size:11.5px;font-weight:600;flex-shrink:0}
.chip-eligible{background:#15351f;color:#6fe08a}
.chip-maybe{background:#33301a;color:#e0c366}
.chip-research{background:#182a3a;color:#86b8e6}
.chip-inhand{background:#2b2b2b;color:#a5a5a5}
.dl{display:block;margin-top:9px;font-size:13px;color:#c9c9c9}
.dl.urgent{color:#ff8f6b;font-weight:700}
.dl.gray{color:#8a8a8a}
a{word-break:break-word}
</style></head><body><div class='wrap'>
<h1>Formation Grants — Open Opportunities Not Yet Applied For</h1>
%(link)s
<input id='q' placeholder='Filter grants… (name, focus, deadline)' autocomplete='off'>
<div class='section-head'>Open opportunities — %(n_active)s</div>
<div class='grid'>%(active)s</div>
<div class='section-head'>Already applied / receiving — %(n_inhand)s</div>
<div class='grid'>%(inhand)s</div>
<small class='small'>Exported %(today)s. Public — deliberately not indexed by search engines.</small>
</div>
<script>
const q=document.getElementById('q'),cards=[...document.querySelectorAll('.card')];
q.addEventListener('input',()=>{const v=q.value.toLowerCase();
cards.forEach(c=>{c.style.display=c.textContent.toLowerCase().includes(v)?'':'none'})});
</script></body></html>""" % {'link': link_line, 'active': cards_active,
                              'inhand': cards_inhand,
                              'n_active': len(active), 'n_inhand': len(inhand),
                              'today': TODAY.isoformat()}
open('site/index.html', 'w').write(PAGE)
print(f"wrote site/index.html with {len(active)} open + {len(inhand)} in-hand cards")